import json,sys
from io import BytesIO
from pathlib import Path
from zipfile import ZipFile
from docx import Document as NativeDocument
from pypdf import PdfReader
import aspose.words_foss as aw
assert 'site-packages' in aw.__file__,aw.__file__
root=Path('/tmp/docweave-boolean-proof');root.mkdir(exist_ok=True)
source=root/'source.docx'
if not source.exists():
 d=NativeDocument();d.add_paragraph().add_run('Underlined text').underline=True;d.save(source)
doc=aw.Document(source);result={}
for kind,field in ((aw.saving.PdfSaveOptions,'export_document_structure'),(aw.saving.MarkdownSaveOptions,'export_underline_formatting'),(aw.saving.OoxmlSaveOptions,'pretty_format')):
 options=kind()
 try:
  setattr(options,field,'false');raw=doc.to_bytes(options)
  if field=='export_document_structure':enabled='/StructTreeRoot' in PdfReader(BytesIO(raw),strict=True).trailer['/Root']
  elif field=='export_underline_formatting':enabled='++Underlined text++' in raw.decode()
  else:
   with ZipFile(BytesIO(raw)) as z:enabled=b'<w:body>\r\n' in z.read('word/document.xml')
  result[field]={'string_accepted':True,'observed_switch_enabled':enabled}
 except ValueError as exc:result[field]={'string_accepted':False,'error':str(exc),'original_value':getattr(options,field)}
Path(sys.argv[1]).write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
